/**
 * `agent/hooks/*.ts`: observe-only event subscribers.
 */
import { basename, extname, relative } from "node:path";
import { getDefinitionKind } from "../brand.js";
import { displayPath } from "./context.js";
import { isDirectory, isModuleFile, toPosix, walkFiles } from "./fs.js";
import { importDefault } from "./modules.js";
export async function loadHooks(ctx, hooksDir, onDisable) {
    if (!(await isDirectory(hooksDir))) {
        return [];
    }
    const hooks = [];
    for (const filePath of await walkFiles(hooksDir)) {
        if (!isModuleFile(basename(filePath))) {
            continue;
        }
        const rel = toPosix(relative(hooksDir, filePath));
        const name = rel.slice(0, -extname(rel).length);
        if (name.includes("__")) {
            ctx.diagnostics.push({
                severity: "error",
                path: displayPath(ctx, filePath),
                message: `Hook name "${name}" may not contain "__"; it is reserved for extension contributions (\`<ns>__<name>\`).`,
            });
            continue;
        }
        const definition = await importDefault(ctx, filePath, onDisable === undefined ? "hook" : ["hook", "disabled"]);
        if (definition === undefined) {
            continue;
        }
        if (getDefinitionKind(definition) === "disabled") {
            onDisable?.(name, filePath);
            continue;
        }
        // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the loader already checked this definition brand; importDefault returns unknown
        const hook = definition;
        if (typeof hook.events !== "object" ||
            hook.events === null ||
            Object.keys(hook.events).length === 0) {
            ctx.diagnostics.push({
                severity: "warning",
                path: displayPath(ctx, filePath),
                message: "Hook declares no event handlers.",
            });
            continue;
        }
        hooks.push({ name, definition: hook });
    }
    return hooks;
}
